# Sid, 2026-10-21 (Phase 10 audit, P1: the log column's group cue "Every recipe" / "This recipe only" drawn in the caption face instead of the Group cue; sketch 013 decision 25).
# Builds the P10_Scales board to publish the way plan 10-09 built the fixture: the approved snapshot's style block kept byte for byte except the .mk-cue rule (now the record pen's
# Group cue face, as p10.py draws it today), and the markup regenerated by p10.py (the Kind radio names per card, the panel heights). Today's p10.py inlines today's app CSS (the
# Phase 9 and 10 build), so a plain regeneration would carry 1,295 lines of app rules the approved board never held; this keeps the approved block.
#   python3 p10-restyle.py <snapshot scales-and-problems.html> <regenerated project/P10_Scales.dc.html> <out .dc.html>
import re, sys, difflib
snap, new, out = [open(p).read() for p in sys.argv[1:3]] + [sys.argv[3]]
def split(s):
    m = re.search(r'<style[^>]*>(.*?)</style>', s, re.S); return s[:m.start(1)], m.group(1), s[m.end(1):]
s_head, s_sty, s_tail = split(snap); n_head, n_sty, n_tail = split(new)
OLD = {'.pc1366 .mk-cue{margin:0}', '.pc393 .mk-cue{margin:0}'}
NEW = {c: re.search(r'^%s \.notebook-log \.mk-cue\{[^}]*\}$' % re.escape(c), n_sty, re.M).group(0) for c in ('.pc1366', '.pc393')}
assert all(NEW[c].startswith(c + ' .notebook-log .mk-cue{margin:0;font-size:var(--app-size-meta);font-weight:600;') for c in NEW), NEW
sty = s_sty
for c in NEW:
    old = c + ' .mk-cue{margin:0}'; assert sty.count(old) == 1, old; sty = sty.replace(old, NEW[c])
# the markup: the regenerated one, which must differ from the snapshot's only in the board's height and top figures
body_s = s_head + s_tail; body_n = (n_head + n_tail).replace('<script src="./support.js"></script>\n', '', 1)   # the snapshot drops the canvas's support.js line
d = [l for l in difflib.unified_diff(body_s.split('\n'), body_n.split('\n'), lineterm='', n=0) if not l.startswith(('---', '+++', '@@'))]
norm = lambda l: re.sub(r'(height: ?|"height": ?|top:)\d+', r'\1H', l[1:])   # the panels' heights and, below the first row, their tops
pairs = list(zip([norm(l) for l in d if l.startswith('-')], [norm(l) for l in d if l.startswith('+')]))
assert all(a == b for a, b in pairs) and len([l for l in d if l.startswith('-')]) == len([l for l in d if l.startswith('+')]), d
open(out, 'w').write(n_head + sty + n_tail)
# report: the style block is the approved one except the cue rule
ds = [l for l in difflib.unified_diff(s_sty.split('\n'), sty.split('\n'), lineterm='', n=0) if not l.startswith(('---', '+++', '@@'))]
print('style diff lines:', len(ds)); [print(' ', l[:160]) for l in ds]; print('markup lines differing (heights and tops only):', len(pairs))
